package com.greatleyposhley.professy.collaboration;
import org.springframework.web.bind.annotation.*;
import java.util.*;
/** Shared directory exposes display details, never account credentials. */
@RestController @RequestMapping("/api/session")
public class PeopleDirectoryController {
 private final WorkAccess access;public PeopleDirectoryController(WorkAccess access){this.access=access;}
 @GetMapping("/directory")public Object directory(){var actor=access.actor();var people=access.jdbc.queryForList("SELECT u.id,CONCAT(u.first_name,' ',u.last_name) AS name,u.email,COALESCE(r.name,'') AS designation,u.profile_picture_url AS avatar,d.name AS department,f.name AS functionName,v.name AS division FROM user_account u LEFT JOIN organization_units d ON d.id=u.department_id AND d.org_id=u.org_id LEFT JOIN organization_units f ON f.id=u.function_id AND f.org_id=u.org_id LEFT JOIN organization_units v ON v.id=u.division_id AND v.org_id=u.org_id LEFT JOIN roles r ON r.id=u.role_id AND r.org_id=u.org_id WHERE u.org_id=? AND u.is_active=1 ORDER BY u.first_name,u.last_name,u.id",actor.getOrgId());var teams=access.jdbc.queryForList("SELECT id,name FROM teams WHERE org_id=? ORDER BY name",actor.getOrgId());for(var team:teams)team.put("members",access.jdbc.queryForList("SELECT tm.user_id FROM team_members tm JOIN user_account u ON u.id=tm.user_id WHERE tm.team_id=? AND u.org_id=? AND u.is_active=1",Long.class,team.get("id"),actor.getOrgId()));return Map.of("people",people,"teams",teams);}
 @GetMapping("/people")public Object people(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int offset){var actor=access.actor();int start=Math.max(0,Math.min(offset,1000000));String search="%"+q.trim().replace("!","!!").replace("%","!%").replace("_","!_")+"%";var rows=access.jdbc.queryForList("SELECT u.id,CONCAT(u.first_name,' ',u.last_name) AS name,u.email,COALESCE(r.name,'') AS designation,u.profile_picture_url AS avatar,d.name AS department,f.name AS functionName,v.name AS division FROM user_account u LEFT JOIN organization_units d ON d.id=u.department_id AND d.org_id=u.org_id LEFT JOIN organization_units f ON f.id=u.function_id AND f.org_id=u.org_id LEFT JOIN organization_units v ON v.id=u.division_id AND v.org_id=u.org_id LEFT JOIN roles r ON r.id=u.role_id AND r.org_id=u.org_id WHERE u.org_id=? AND u.is_active=1 AND CONCAT(u.first_name,' ',u.last_name,' ',u.email,' ',COALESCE(r.name,'')) LIKE ? ESCAPE '!' ORDER BY u.first_name,u.last_name,u.id LIMIT 51 OFFSET ?",actor.getOrgId(),search,start);boolean more=rows.size()>50;if(more)rows=rows.subList(0,50);return Map.of("people",rows,"nextOffset",more?start+50:-1);}
}
